DECLARE
  jt_value text;
BEGIN
  jt_value := NEW.raw_user_meta_data->>'job_title';

  INSERT INTO public.user_profiles (user_id, employee_code, full_name, job_title, is_active)
  VALUES (
    NEW.id,
    'EMP-' || UPPER(SUBSTRING(NEW.id::text, 1, 6)),
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    CASE WHEN jt_value IS NOT NULL THEN jt_value::public.job_title_level ELSE NULL END,
    true
  );
  RETURN NEW;
END;

declare
  next_ver int;
  prev_current_id uuid;
begin
  -- Determine next version for this (project_id, doc_type)
  select coalesce(max(d.version), 0) + 1
    into next_ver
  from public.documents d
  where d.project_id = new.project_id
    and d.doc_type = new.doc_type;

  new.version := next_ver;
  new.is_current := true;

  -- Mark previous current as not current (if any)
  update public.documents
     set is_current = false,
         updated_at = now()
   where project_id = new.project_id
     and doc_type = new.doc_type
     and is_current = true;

  -- Update project's current document pointer
  if new.doc_type = 'offer' then
    update public.projects
       set current_offer_id = new.id,
           updated_at = now()
     where id = new.project_id;
  else
    update public.projects
       set current_submittal_id = new.id,
           updated_at = now()
     where id = new.project_id;
  end if;

  return new;
end

begin
  new.updated_at = now();
  return new;
end

