declare
  v_user_id uuid;
begin
  -- Only run when status changes
  if new.status is distinct from old.status then

    -- Read app user from the DB session (set by backend in same transaction)
    v_user_id := nullif(current_setting('app.user_id', true), '')::uuid;

    if v_user_id is null then
      raise exception
        using message = 'Missing app.user_id in DB session. Backend must do: SET LOCAL app.user_id = ''<uuid>'' inside the same transaction.',
              errcode = '22023';
    end if;

    -- Require reason when status becomes lost or cancelled
    if new.status in ('lost') then
      if new.status_reason is null or btrim(new.status_reason) = '' then
        raise exception
          using message = 'status_reason is required when status becomes lost or cancelled',
                errcode = '23514';
      end if;
    end if;

    -- If status becomes won: our_price is required
    if new.status = 'won' then
      if new.status_our_price is null then
        raise exception
          using message = 'status_our_price is required when status becomes won',
                errcode = '23514';
      end if;
    end if;

    -- If status becomes lost: require competitor + both prices
    if new.status = 'lost' then
      if new.status_our_price is null then
        raise exception
          using message = 'status_our_price is required when status becomes lost',
                errcode = '23514';
      end if;

      if new.status_competitor_price is null then
        raise exception
          using message = 'status_competitor_price is required when status becomes lost',
                errcode = '23514';
      end if;

      if new.status_competitor_name is null or btrim(new.status_competitor_name) = '' then
        raise exception
          using message = 'status_competitor_name is required when status becomes lost',
                errcode = '23514';
      end if;
    end if;

    -- Insert history row
    insert into public.project_status_history (
      project_id,
      from_status,
      to_status,
      changed_by_user_id,
      changed_at,
      reason,
      notes,
      meta,
      our_price,
      competitor_name,
      competitor_price
    ) values (
      new.id,
      old.status,
      new.status,
      v_user_id,
      now(),
      new.status_reason,
      new.status_notes,
      new.status_meta,
      new.status_our_price,
      new.status_competitor_name,
      new.status_competitor_price
    );

    -- Clear transient fields so they aren't accidentally reused
    new.status_reason := null;
    new.status_notes := null;
    new.status_meta := '{}'::jsonb;
    new.status_our_price := null;
    new.status_competitor_name := null;
    new.status_competitor_price := null;

  end if;

  return new;
end

begin
  new.updated_at = now();
  return new;
end
